from pyspark.sql import functions as F


def make_tasks(shipments, shipment_events, deliveries):
    def clean_events():
        missing = shipment_events.filter(F.col("event_id").isNull() | F.col("shipment_id").isNull()).count()
        if missing > 0:
            raise ValueError(f"{missing} events without an event_id or shipment_id")
        return shipment_events.select([c for c in shipment_events.columns if c != "load_date"]).distinct()

    def known_events(clean_events):
        ids = [r.shipment_id for r in shipments.select("shipment_id").collect()]
        unknown = clean_events.filter(~F.col("shipment_id").isin(ids)).count()
        if unknown > 0:
            raise ValueError(f"{unknown} events for unknown shipments")
        return clean_events

    def delivered(known_events):
        return known_events.filter(F.col("event_type") == "delivered")

    def late_deliveries():
        allowed = F.col("status").isin("on_time", "late", "failed")
        bad = deliveries.filter(~F.coalesce(allowed, F.lit(False))).count()
        if bad > 0:
            raise ValueError(f"{bad} deliveries with an unknown status")
        return deliveries.filter(F.col("status") == "late")

    def late_scans(delivered, late_deliveries):
        late_ids = [r.shipment_id for r in late_deliveries.select("shipment_id").collect()]
        return delivered.filter(F.col("shipment_id").isin(late_ids))

    return {
        "late_scans": (late_scans, ["delivered", "late_deliveries"]),
        "delivered": (delivered, ["known_events"]),
        "known_events": (known_events, ["clean_events"]),
        "clean_events": (clean_events, []),
        "late_deliveries": (late_deliveries, []),
    }


def run_order(deps):
    order = []
    while len(order) < len(deps):
        ready = [t for t in deps if t not in order and all(d in order for d in deps[t])]
        if not ready:
            raise ValueError("these tasks wait on each other: " + ", ".join(t for t in deps if t not in order))
        order += ready
    return order


def solve(shipments, shipment_events, deliveries):
    tasks = make_tasks(shipments, shipment_events, deliveries)
